module.exports = {
  "account": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0627\u0644\u0623\u0645\u0627\u0646</span><h1>\u062d\u0633\u0627\u0628\u064a</h1><p class=\"muted\">\u063a\u064a\u0651\u0631 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631\u0643 \u0645\u0646 \u0647\u0646\u0627. \u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0631\u0635\u064a\u062f \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u062d\u0629.</p></div></div>\n<section class=\"card narrow-card\"><h2>\u062a\u063a\u064a\u064a\u0631 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631</h2><form method=\"post\" action=\"/account/password\"><label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062d\u0627\u0644\u064a\u0629<input type=\"password\" name=\"current_password\" required autocomplete=\"current-password\"></label><label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062c\u062f\u064a\u062f\u0629<input type=\"password\" name=\"new_password\" minlength=\"8\" required autocomplete=\"new-password\"></label><label>\u062a\u0623\u0643\u064a\u062f \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631<input type=\"password\" name=\"confirm_password\" minlength=\"8\" required autocomplete=\"new-password\"></label><button class=\"primary full\">\u062d\u0641\u0638 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631</button></form></section>\n<%- include('partials/footer') %>\n",
  "rank": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0631\u062d\u0644\u062a\u0643 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0643\u062a\u0628\u0629</span><h1>\u0631\u062a\u0628\u062a\u064a</h1><p class=\"muted\">\u0643\u0644 \u0631\u062a\u0628\u0629 \u0645\u062d\u0637\u0629 \u062c\u062f\u064a\u062f\u0629\u060c \u0648\u0627\u0644\u0631\u062a\u0628\u0629 \u0644\u0627 \u062a\u0646\u062e\u0641\u0636 \u0639\u0646\u062f \u0635\u0631\u0641 \u0631\u0635\u064a\u062f\u0643 \u0641\u064a \u0627\u0644\u0645\u062a\u062c\u0631.</p></div></div>\n<section class=\"rank-current\"><div class=\"rank-icon\"><%= p.rank.icon %></div><div><span>\u0623\u0646\u062a \u0627\u0644\u0622\u0646</span><h2><%= p.rank.name %></h2><p><%= p.rank.description %></p></div><strong><%= p.lifetime_minutes %> \u062f\u0642\u064a\u0642\u0629</strong></section>\n<% if(p.nextRank){ const range=p.nextRank.min_minutes-p.rank.min_minutes; const done=p.lifetime_minutes-p.rank.min_minutes; const pct=Math.max(0,Math.min(100,Math.round(done/range*100))); %><section class=\"card rank-next\"><div class=\"row-between\"><div><span class=\"eyebrow\">\u0627\u0644\u0645\u062d\u0637\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629</span><h2><%= p.nextRank.icon %> <%= p.nextRank.name %></h2></div><strong>\u0628\u0627\u0642\u064a <%= p.nextRank.min_minutes-p.lifetime_minutes %> \u062f\u0642\u064a\u0642\u0629</strong></div><div class=\"progress large\"><i style=\"width:<%= pct %>%\"></i></div><small><%= p.lifetime_minutes %> / <%= p.nextRank.min_minutes %> \u062f\u0642\u064a\u0642\u0629</small></section><% } %>\n<div class=\"rank-path journey-path\"><% ranks.forEach((r,i)=>{ const reached=p.lifetime_minutes>=r.min_minutes; const current=r.id===p.rank.id; %><div class=\"rank-step <%= reached?'reached':'' %> <%= current?'current':'' %>\"><div class=\"rank-marker\"><span><%= r.icon %></span></div><div><b><%= r.name %> <%= current?'<span class=\"you-are-here\">\u0623\u0646\u062a \u0647\u0646\u0627</span>':'' %></b><small><%= r.description %></small><small>\u062a\u0628\u062f\u0623 \u0645\u0646 <%= r.min_minutes %> \u062f\u0642\u064a\u0642\u0629</small></div><i><%= reached?'\u2713':i+1 %></i></div><% }) %></div>\n<%- include('partials/footer') %>\n",
  "store": "<%- include('partials/header') %>\n<div class=\"page-head store-head\"><div><span class=\"eyebrow\">\u0627\u0633\u062a\u062b\u0645\u0631 \u062f\u0642\u0627\u0626\u0642\u0643</span><h1>\u0645\u062a\u062c\u0631 \u0627\u0644\u0645\u0643\u062a\u0628\u0629</h1><p class=\"muted\">\u0627\u062e\u062a\u0631 \u0645\u0643\u0627\u0641\u0623\u0629 \u062a\u0646\u0627\u0633\u0628 \u0631\u0635\u064a\u062f\u0643\u060c \u0623\u0648 \u0627\u0639\u0631\u0641 \u0643\u0645 \u0628\u0642\u064a \u0644\u0643 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647\u0627.</p></div><div class=\"wallet-pill big\">\u0631\u0635\u064a\u062f\u0643 <b><%= p.wallet_minutes %></b> \u062f\u0642\u064a\u0642\u0629</div></div>\n<% const available=rewards.filter(r=>{const rankOk=!r.min_rank_minutes||p.lifetime_minutes>=r.min_rank_minutes;return p.wallet_minutes>=r.price_minutes&&rankOk&&(!r.purchase_limit||r.my_purchases<r.purchase_limit)&&r.quantity>0}); const locked=rewards.filter(r=>!available.includes(r)); %>\n<% if(available.length){ %><div class=\"store-section-title\"><div><span>\u2728</span><div><h2>\u0645\u062a\u0627\u062d \u0644\u0643 \u0627\u0644\u0622\u0646</h2><p>\u0645\u0643\u0627\u0641\u0622\u062a \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0633\u062a\u0628\u062f\u0627\u0644\u0647\u0627 \u0641\u0648\u0631\u064b\u0627</p></div></div></div><div class=\"reward-grid\"><% available.forEach(r=>{ %><article class=\"reward-card available\"><div class=\"reward-icon\"><%= r.icon %></div><span class=\"stock\">\u0645\u062a\u0628\u0642\u064a <%= r.quantity %></span><span class=\"ready-badge\">\u062c\u0627\u0647\u0632\u0629 \u0644\u0643</span><h3><%= r.name %></h3><p><%= r.description %></p><div class=\"price\"><b><%= r.price_minutes %></b> \u062f\u0642\u064a\u0642\u0629</div><% if(r.min_rank_name){ %><small>\u0645\u062a\u0627\u062d\u0629 \u0645\u0646 \u0631\u062a\u0628\u0629: <%= r.min_rank_name %></small><% } %><form method=\"post\" action=\"/store/<%= r.id %>/buy\"><button class=\"primary full\" data-confirm=\"\u062a\u0623\u0643\u064a\u062f \u0627\u0633\u062a\u0628\u062f\u0627\u0644 <%= r.price_minutes %> \u062f\u0642\u064a\u0642\u0629 \u0645\u0642\u0627\u0628\u0644 <%= r.name %>\u061f\">\u0627\u0633\u062a\u0628\u062f\u0644 \u0627\u0644\u0622\u0646</button></form></article><% }) %></div><% } %>\n\n<% if(locked.length){ %><div class=\"store-section-title locked-title\"><div><span>\ud83d\udd12</span><div><h2>\u0627\u0642\u062a\u0631\u0628\u062a \u0645\u0646\u0647\u0627</h2><p>\u0648\u0627\u0635\u0644 \u0631\u062d\u0644\u062a\u0643 \u0644\u0641\u062a\u062d \u0647\u0630\u0647 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062a</p></div></div></div><div class=\"reward-grid\"><% locked.forEach(r=>{ const rankOk=!r.min_rank_minutes||p.lifetime_minutes>=r.min_rank_minutes; const moneyRemain=Math.max(0,r.price_minutes-p.wallet_minutes); const limitOk=!r.purchase_limit||r.my_purchases<r.purchase_limit; %><article class=\"reward-card locked\"><div class=\"reward-icon\"><%= r.icon %></div><span class=\"stock\">\u0645\u062a\u0628\u0642\u064a <%= r.quantity %></span><h3><%= r.name %></h3><p><%= r.description %></p><div class=\"price\"><b><%= r.price_minutes %></b> \u062f\u0642\u064a\u0642\u0629</div><% if(r.quantity<=0){ %><div class=\"unlock-note\">\u0646\u0641\u062f\u062a \u0627\u0644\u0643\u0645\u064a\u0629 \u062d\u0627\u0644\u064a\u064b\u0627</div><% } else if(!rankOk){ %><div class=\"unlock-note\">\ud83d\udd12 \u062a\u062d\u062a\u0627\u062c \u0631\u062a\u0628\u0629 \u00ab<%= r.min_rank_name %>\u00bb</div><% } else if(!limitOk){ %><div class=\"unlock-note\">\u0648\u0635\u0644\u062a \u0644\u0644\u062d\u062f \u0627\u0644\u0645\u0633\u0645\u0648\u062d</div><% } else { %><div class=\"unlock-note\">\ud83d\udd25 \u0628\u0627\u0642\u064a \u0644\u0643 <b><%= moneyRemain %></b> \u062f\u0642\u064a\u0642\u0629 \u0641\u0642\u0637</div><% } %><button class=\"ghost full\" disabled>\u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0627\u0644\u0622\u0646</button></article><% }) %></div><% } %>\n<% if(!rewards.length){ %><div class=\"empty\">\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0643\u0627\u0641\u0622\u062a \u0645\u062a\u0627\u062d\u0629 \u062d\u0627\u0644\u064a\u064b\u0627.</div><% } %>\n<%- include('partials/footer') %>\n",
  "admin-participants": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a</span><h1>\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646</h1><p class=\"muted\">\u0627\u0644\u0631\u0635\u064a\u062f \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0645\u0646 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0634\u0627\u0631\u0643. \u0623\u064a \u062a\u0639\u062f\u064a\u0644 \u0625\u062f\u0627\u0631\u064a \u0647\u0646\u0627 \u064a\u0633\u062c\u0644 \u0641\u064a \u0633\u062c\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062a.</p></div></div>\n<section class=\"card\"><h2>\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0627\u0631\u0643</h2><form class=\"form-row\" method=\"post\" action=\"/admin/participants/add\"><input name=\"name\" placeholder=\"\u0627\u0644\u0627\u0633\u0645\" required><input name=\"username\" placeholder=\"\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" required><input name=\"password\" type=\"password\" minlength=\"8\" placeholder=\"\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0645\u0624\u0642\u062a\u0629\" required><button class=\"primary\">\u0625\u0636\u0627\u0641\u0629</button></form></section>\n<div class=\"admin-list\"><% participants.forEach(p=>{ const rank=p.rank; %><article class=\"card participant-admin-card\"><div class=\"row-between\"><div><h3><%= p.name %></h3><small>@<%= p.username %> \u2022 <%= rank.icon %> <%= rank.name %> \u2022 <%= p.active?'\u0646\u0634\u0637':'\u0645\u0639\u0637\u0644' %></small></div><div class=\"mini-stats\"><span>\u0627\u0644\u0631\u062d\u0644\u0629 <b><%= p.lifetime_minutes %></b></span><span>\u0627\u0644\u0631\u0635\u064a\u062f <b><%= p.wallet_minutes %></b></span><span>\u0642\u0631\u0627\u0621\u0629 <b><%= p.reading_minutes %></b></span><span>\u0627\u0633\u062a\u0645\u0627\u0639 <b><%= p.listening_minutes %></b></span></div></div>\n<details><summary>\u062a\u0639\u062f\u064a\u0644 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628</summary><form class=\"form-row\" method=\"post\" action=\"/admin/participants/<%= p.id %>/update\"><input name=\"name\" value=\"<%= p.name %>\" required><input name=\"username\" value=\"<%= p.username %>\" required><input name=\"new_password\" type=\"password\" minlength=\"8\" placeholder=\"\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062c\u062f\u064a\u062f\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)\"><button class=\"primary\">\u062d\u0641\u0638</button></form></details>\n<div class=\"admin-actions\"><form method=\"post\" action=\"/admin/participants/<%= p.id %>/toggle\"><button class=\"ghost\"><%= p.active?'\u062a\u0639\u0637\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628':'\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628' %></button></form><form class=\"form-row compact\" method=\"post\" action=\"/admin/participants/<%= p.id %>/adjust\"><input name=\"amount\" type=\"number\" step=\"1\" placeholder=\"+ \u0623\u0648 - \u062f\u0642\u0627\u0626\u0642\" required><input name=\"reason\" placeholder=\"\u0633\u0628\u0628 \u0627\u0644\u062a\u0639\u062f\u064a\u0644\" required><button class=\"ghost\">\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u062f\u0642\u0627\u0626\u0642</button></form></div></article><% }) %></div>\n<%- include('partials/footer') %>\n",
  "admin-transactions": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u062a\u062f\u0642\u064a\u0642 \u0643\u0627\u0645\u0644</span><h1>\u0633\u062c\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062a</h1><p class=\"muted\">\u0622\u062e\u0631 500 \u0639\u0645\u0644\u064a\u0629 \u0645\u0639 \u0627\u0644\u0631\u0635\u064a\u062f \u0642\u0628\u0644 \u0648\u0628\u0639\u062f \u0648\u0645\u0646 \u0646\u0641\u0630 \u0627\u0644\u0639\u0645\u0644\u064a\u0629.</p></div></div><section class=\"card table-wrap\"><table><thead><tr><th>\u0627\u0644\u062a\u0627\u0631\u064a\u062e</th><th>\u0627\u0644\u0645\u0634\u0627\u0631\u0643</th><th>\u0627\u0644\u0646\u0648\u0639</th><th>\u0627\u0644\u062f\u0642\u0627\u0626\u0642</th><th>\u0627\u0644\u0631\u0635\u064a\u062f \u0642\u0628\u0644</th><th>\u0627\u0644\u0631\u0635\u064a\u062f \u0628\u0639\u062f</th><th>\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0631\u062d\u0644\u0629 \u0642\u0628\u0644</th><th>\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0631\u062d\u0644\u0629 \u0628\u0639\u062f</th><th>\u0627\u0644\u0633\u0628\u0628</th><th>\u0646\u0641\u0630\u0647\u0627</th></tr></thead><tbody><% rows.forEach(t=>{ %><tr><td><%= new Date(t.created_at).toLocaleString('ar-SA') %></td><td><%= t.participant_name %></td><td><%= t.kind %></td><td><%= t.amount %></td><td><%= t.wallet_before %></td><td><%= t.wallet_after %></td><td><%= t.lifetime_before %></td><td><%= t.lifetime_after %></td><td><%= t.reason||'-' %></td><td><%= t.actor_name||'\u0627\u0644\u0646\u0638\u0627\u0645' %></td></tr><% }) %></tbody></table></section><%- include('partials/footer') %>\n",
  "admin-staff": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0627\u0644\u0645\u062f\u064a\u0631</span><h1>\u0627\u0644\u0645\u0634\u0631\u0641\u0648\u0646</h1></div></div><section class=\"card\"><h2>\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641</h2><form class=\"form-row\" method=\"post\" action=\"/admin/staff/add\"><input name=\"name\" placeholder=\"\u0627\u0644\u0627\u0633\u0645\" required><input name=\"username\" placeholder=\"\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" required><input name=\"password\" type=\"password\" minlength=\"8\" placeholder=\"\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631\" required><button class=\"primary\">\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641</button></form></section><div class=\"admin-list\"><% staff.forEach(s=>{ %><article class=\"card\"><div class=\"row-between\"><div><h3><%= s.name %></h3><small>@<%= s.username %> \u2022 <%= s.role==='manager'?'\u0645\u062f\u064a\u0631':'\u0645\u0634\u0631\u0641' %> \u2022 <%= s.active?'\u0646\u0634\u0637':'\u0645\u0639\u0637\u0644' %></small></div><% if(s.role==='supervisor'){ %><form method=\"post\" action=\"/admin/staff/<%= s.id %>/toggle\"><button class=\"ghost\"><%= s.active?'\u062a\u0639\u0637\u064a\u0644':'\u062a\u0641\u0639\u064a\u0644' %></button></form><% } %></div><% if(s.role==='supervisor'){ %><form class=\"form-row compact\" method=\"post\" action=\"/admin/staff/<%= s.id %>/password\"><input name=\"new_password\" type=\"password\" minlength=\"8\" placeholder=\"\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062c\u062f\u064a\u062f\u0629\" required><button class=\"ghost\">\u062a\u063a\u064a\u064a\u0631 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631</button></form><% } %></article><% }) %></div><%- include('partials/footer') %>\n",
  "admin-approvals": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a</span><h1>\u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629</h1></div><span class=\"badge\"><%= logs.length %> \u0628\u0627\u0646\u062a\u0638\u0627\u0631\u0643</span></div><div class=\"approval-list\"><% if(!logs.length){ %><div class=\"empty\">\u0644\u0627 \u062a\u0648\u062c\u062f \u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0645\u0639\u0644\u0642\u0629 \ud83c\udf89</div><% } %><% logs.forEach(l=>{ %><article class=\"card approval\"><div><span class=\"avatar\"><%= l.name.charAt(0) %></span><div><h3><%= l.name %></h3><p>\u0627\u0644\u0623\u0633\u0628\u0648\u0639 <%= l.week_number %> \u2014 <%= l.activity_type==='reading'?'\ud83d\udcd6 \u0642\u0631\u0627\u0621\u0629':'\ud83c\udfa7 \u0627\u0633\u062a\u0645\u0627\u0639' %></p></div></div><strong><%= l.minutes %> \u062f\u0642\u064a\u0642\u0629</strong><form method=\"post\"><input name=\"note\" placeholder=\"\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629\"><div class=\"actions\"><button class=\"primary\" formaction=\"/admin/approvals/<%= l.id %>/approve\">\u2713 \u0627\u0639\u062a\u0645\u0627\u062f</button><button class=\"danger\" formaction=\"/admin/approvals/<%= l.id %>/reject\">\u0631\u0641\u0636</button></div></form></article><% }) %></div><%- include('partials/footer') %>\n",
  "leaderboard": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0623\u0647\u0644 \u0627\u0644\u0625\u0646\u062c\u0627\u0632</span><h1>\ud83c\udfc6 \u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u062a\u0645\u064a\u0632\u064a\u0646</h1></div></div><div class=\"podium\"><% rows.slice(0,3).forEach((r,i)=>{ %><div class=\"podium-card place-<%= i+1 %>\"><span><%= i===0?'\ud83e\udd47':i===1?'\ud83e\udd48':'\ud83e\udd49' %></span><h3><%= r.name %></h3><b><%= r.lifetime_minutes %> \u062f\u0642\u064a\u0642\u0629</b></div><% }) %></div><section class=\"card\"><table><thead><tr><th>#</th><th>\u0627\u0644\u0645\u0634\u0627\u0631\u0643</th><th>\u0627\u0644\u0642\u0631\u0627\u0621\u0629</th><th>\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639</th><th>\u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a</th></tr></thead><tbody><% rows.forEach((r,i)=>{ %><tr><td><%= i+1 %></td><td><b><%= r.name %></b></td><td><%= r.reading_minutes %></td><td><%= r.listening_minutes %></td><td><%= r.lifetime_minutes %></td></tr><% }) %></tbody></table></section><%- include('partials/footer') %>\n",
  "login": "<%- include('partials/header') %>\n<div class=\"login-wrap\">\n  <div class=\"login-card\">\n    <div class=\"login-visual\">\n      <div class=\"shelf\"><svg class=\"logo-mark\" viewBox=\"0 0 48 48\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><path d=\"M24 13c-4.2-3-9.4-4-14.4-2.8v22.4c5-1.2 10.2-.2 14.4 2.8 4.2-3 9.4-4 14.4-2.8V10.2C33.4 9 28.2 10 24 13Z\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M24 13v22.4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></div>\n      <h1>\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u0642\u0627\u0631\u0626</h1>\n      <p>\u0627\u0642\u0631\u0623\u060c \u0627\u0633\u0645\u0639\u060c \u0627\u062c\u0645\u0639 \u0631\u0635\u064a\u062f\u0643\u060c \u0648\u0627\u0631\u062a\u0642\u0650 \u0641\u064a \u0645\u0643\u062a\u0628\u062a\u0643.</p>\n    </div>\n    <div class=\"login-form\">\n      <h2>\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644</h2>\n      <p class=\"muted\">\u0645\u0631\u062d\u0628\u064b\u0627 \u0628\u0639\u0648\u062f\u062a\u0643 \u0625\u0644\u0649 \u0631\u062d\u0644\u062a\u0643 \u0627\u0644\u0642\u0631\u0627\u0626\u064a\u0629.</p>\n      <% if(typeof error!=='undefined'){ %><div class=\"flash error\"><%= error %></div><% } %>\n      <form method=\"post\" action=\"/login\">\n        <label>\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645<input name=\"username\" required autocomplete=\"username\"></label>\n        <label>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631<input name=\"password\" type=\"password\" required autocomplete=\"current-password\"></label>\n        <button class=\"primary full\">\u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u0643\u062a\u0628\u0629</button>\n      </form>\n    </div>\n  </div>\n</div>\n<%- include('partials/footer') %>\n",
  "admin-dashboard": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c</span><h1>\u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u062d\u0643\u0645</h1></div></div><div class=\"grid stats\"><div class=\"card\"><span>\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646</span><strong><%= stats.participants %></strong><small>\u062d\u0633\u0627\u0628 \u0646\u0634\u0637</small></div><div class=\"card\"><span>\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f</span><strong><%= stats.pending %></strong><small>\u0625\u0646\u062c\u0627\u0632</small></div><div class=\"card\"><span>\u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062a</span><strong><%= stats.rewards %></strong><small>\u0645\u0643\u0627\u0641\u0623\u0629 \u0645\u062a\u0627\u062d\u0629</small></div><div class=\"card\"><span>\u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0645\u0633\u062a\u0628\u062f\u0644\u0629</span><strong><%= stats.spent %></strong><small>\u062f\u0642\u064a\u0642\u0629</small></div></div><section class=\"card\"><div class=\"section-title\"><h2>\u0623\u062d\u062f\u062b \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629</h2><a href=\"/admin/approvals\">\u0639\u0631\u0636 \u0627\u0644\u0643\u0644</a></div><div class=\"table-wrap\"><table><thead><tr><th>\u0627\u0644\u0645\u0634\u0627\u0631\u0643</th><th>\u0627\u0644\u0623\u0633\u0628\u0648\u0639</th><th>\u0627\u0644\u0646\u0648\u0639</th><th>\u0627\u0644\u062f\u0642\u0627\u0626\u0642</th></tr></thead><tbody><% pending.forEach(l=>{ %><tr><td><b><%= l.name %></b></td><td><%= l.week_number %></td><td><%= l.activity_type==='reading'?'\ud83d\udcd6 \u0642\u0631\u0627\u0621\u0629':'\ud83c\udfa7 \u0627\u0633\u062a\u0645\u0627\u0639' %></td><td><%= l.minutes %></td></tr><% }) %></tbody></table></div></section><%- include('partials/footer') %>\n",
  "dashboard": "<%- include('partials/header') %>\n<% const readRemain=week?Math.max(0,week.reading_target-progress.reading):0; const listenRemain=week?Math.max(0,week.listening_target-progress.listening):0; const readEffective=week?progress.reading+pending.reading:0; const listenEffective=week?progress.listening+pending.listening:0; const weekDone=week&&readRemain===0&&listenRemain===0; const weekWaiting=week&&!weekDone&&readEffective>=week.reading_target&&listenEffective>=week.listening_target; const rankRemain=p.nextRank?Math.max(0,p.nextRank.min_minutes-p.lifetime_minutes):0; %>\n<section class=\"hero hero-dashboard\"><div><span class=\"eyebrow\">\u0623\u0647\u0644\u064b\u0627 \u0628\u0643 \u0641\u064a \u0645\u0643\u062a\u0628\u062a\u0643 \ud83d\udc4b\ud83c\udffb</span><h1><%= p.rank.icon %> <%= p.rank.name %></h1><p>\u0643\u0644 \u062f\u0642\u064a\u0642\u0629 \u062a\u0636\u064a\u0641\u0647\u0627 \u062a\u0628\u0646\u064a \u0631\u062d\u0644\u062a\u0643 \u0648\u062a\u0641\u062a\u062d \u0644\u0643 \u0631\u062a\u0628\u0629 \u0648\u0645\u0643\u0627\u0641\u0623\u0629 \u062c\u062f\u064a\u062f\u0629.</p><div class=\"hero-chips\"><span>\ud83d\udd25 <%= p.lifetime_minutes.toLocaleString('ar-SA') %> \u062f\u0642\u064a\u0642\u0629 \u0641\u064a \u0631\u062d\u0644\u062a\u0643</span><span>\ud83e\ude99 <%= p.wallet_minutes.toLocaleString('ar-SA') %> \u062f\u0642\u064a\u0642\u0629 \u0645\u062a\u0627\u062d\u0629</span></div></div><div class=\"book-stack\" aria-hidden=\"true\">\u25b0<br>\u25b0<br>\u25b0</div></section>\n\n<section class=\"next-step card accent-card\">\n  <div class=\"next-step-icon\"><%= !week?'\ud83d\udcda':weekDone?(p.nextRank&&rankRemain<=100?'\ud83c\udfdb\ufe0f':'\u2705'):(readRemain>0?'\ud83d\udcd6':'\ud83c\udfa7') %></div>\n  <div>\n    <span class=\"eyebrow\">\u062e\u0637\u0648\u062a\u0643 \u0627\u0644\u062a\u0627\u0644\u064a\u0629</span>\n    <% if(!week){ %><h2>\u0627\u0633\u062a\u0639\u062f \u0644\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0642\u0627\u062f\u0645</h2><p>\u0644\u0627 \u064a\u0648\u062c\u062f \u0623\u0633\u0628\u0648\u0639 \u0645\u0641\u062a\u0648\u062d \u062d\u0627\u0644\u064a\u064b\u0627\u060c \u0648\u0627\u0635\u0644 \u0631\u062d\u0644\u062a\u0643 \u0645\u0646 \u0627\u0644\u0633\u062c\u0644 \u0648\u0627\u0644\u0645\u062a\u062c\u0631.</p>\n    <% } else if(weekWaiting){ %><h2>\u0625\u0646\u062c\u0627\u0632\u0643 \u0645\u0643\u062a\u0645\u0644 \u0648\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u23f3</h2><p>\u0623\u0631\u0633\u0644\u062a \u0645\u0627 \u064a\u0643\u0641\u064a \u0644\u0625\u0643\u0645\u0627\u0644 \u0647\u062f\u0641 \u0627\u0644\u0623\u0633\u0628\u0648\u0639. \u0628\u0639\u062f \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0641 \u0633\u062a\u0636\u0627\u0641 \u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0625\u0644\u0649 \u0631\u0635\u064a\u062f\u0643.</p><a class=\"primary inline\" href=\"/week\">\u0631\u0627\u062c\u0639 \u0625\u0646\u062c\u0627\u0632\u0643</a>\n    <% } else if(!weekDone){ const readNeed=Math.max(0,week.reading_target-readEffective); const listenNeed=Math.max(0,week.listening_target-listenEffective); %><h2><%= readNeed>0?`\u0628\u0627\u0642\u064a \u0644\u0643 ${readNeed} \u062f\u0642\u064a\u0642\u0629 \u0642\u0631\u0627\u0621\u0629`:`\u0628\u0627\u0642\u064a \u0644\u0643 ${listenNeed} \u062f\u0642\u064a\u0642\u0629 \u0627\u0633\u062a\u0645\u0627\u0639` %></h2><p>\u0623\u0643\u0645\u0644 \u0647\u062f\u0641 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u060c \u0648\u0628\u0639\u062f \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u062a\u0636\u0627\u0641 \u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0645\u0628\u0627\u0634\u0631\u0629 \u0625\u0644\u0649 \u0631\u0635\u064a\u062f\u0643.</p><a class=\"primary inline\" href=\"/week\">\u0633\u062c\u0651\u0644 \u0625\u0646\u062c\u0627\u0632\u0643 \u0627\u0644\u0622\u0646</a>\n    <% } else if(p.nextRank && rankRemain<=100){ %><h2>\u0627\u0642\u062a\u0631\u0628\u062a \u0645\u0646 <%= p.nextRank.name %></h2><p>\u0628\u0627\u0642\u064a \u0644\u0643 <b><%= rankRemain %></b> \u062f\u0642\u064a\u0642\u0629 \u0641\u0642\u0637 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0631\u062a\u0628\u062a\u0643 \u0627\u0644\u062a\u0627\u0644\u064a\u0629.</p><a class=\"primary inline\" href=\"/rank\">\u0634\u0627\u0647\u062f \u0631\u062d\u0644\u0629 \u0627\u0644\u0631\u062a\u0628</a>\n    <% } else if(rewardNow){ %><h2>\u0631\u0635\u064a\u062f\u0643 \u064a\u0643\u0641\u064a \u0644\u0645\u0643\u0627\u0641\u0623\u0629 \u0627\u0644\u0622\u0646 \u2615</h2><p>\u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u00ab<%= rewardNow.name %>\u00bb \u0645\u0642\u0627\u0628\u0644 <%= rewardNow.price_minutes %> \u062f\u0642\u064a\u0642\u0629 \u062f\u0648\u0646 \u0623\u0646 \u062a\u0646\u062e\u0641\u0636 \u0631\u062a\u0628\u062a\u0643.</p><a class=\"primary inline\" href=\"/store\">\u0627\u0641\u062a\u062d \u0627\u0644\u0645\u062a\u062c\u0631</a>\n    <% } else { %><h2>\u0623\u0643\u0645\u0644\u062a \u0647\u062f\u0641 \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \ud83c\udf89</h2><p>\u0645\u0645\u062a\u0627\u0632! \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0627\u0633\u062a\u0645\u0631\u0627\u0631 \u0628\u062f\u0642\u0627\u0626\u0642 \u0625\u0636\u0627\u0641\u064a\u0629 \u0623\u0648 \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062a \u0627\u0644\u0642\u0627\u062f\u0645\u0629.</p><a class=\"primary inline\" href=\"/store\">\u0627\u0633\u062a\u0643\u0634\u0641 \u0627\u0644\u0645\u062a\u062c\u0631</a><% } %>\n  </div>\n</section>\n\n<div class=\"grid dashboard-main\">\n  <section class=\"card weekly-focus\">\n    <div class=\"section-title\"><div><span class=\"eyebrow\">\u0627\u0644\u0623\u0647\u0645 \u0627\u0644\u0622\u0646</span><h2>\u0625\u0646\u062c\u0627\u0632\u0643 \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</h2></div><a href=\"/week\">\u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644</a></div>\n    <% if(week){ %>\n      <div class=\"goal-modern\"><div class=\"goal-head\"><span>\ud83d\udcd6 \u0627\u0644\u0642\u0631\u0627\u0621\u0629</span><b><%= progress.reading %> / <%= week.reading_target %> \u062f\u0642\u064a\u0642\u0629</b></div><div class=\"progress\"><i style=\"width:<%= Math.min(100,Math.round(progress.reading/week.reading_target*100)) %>%\"></i></div><small>\u0645\u0639\u062a\u0645\u062f: <%= progress.reading %> <% if(pending.reading){ %>\u2022 \u0642\u064a\u062f \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629: <%= pending.reading %><% } %> \u2014 <%= readRemain===0?'\u062a\u0645 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0647\u062f\u0641 \u2713':`\u0628\u0627\u0642\u064a ${readRemain} \u062f\u0642\u064a\u0642\u0629 \u0645\u0639\u062a\u0645\u062f\u0629` %></small></div>\n      <div class=\"goal-modern\"><div class=\"goal-head\"><span>\ud83c\udfa7 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639</span><b><%= progress.listening %> / <%= week.listening_target %> \u062f\u0642\u064a\u0642\u0629</b></div><div class=\"progress\"><i style=\"width:<%= Math.min(100,Math.round(progress.listening/week.listening_target*100)) %>%\"></i></div><small>\u0645\u0639\u062a\u0645\u062f: <%= progress.listening %> <% if(pending.listening){ %>\u2022 \u0642\u064a\u062f \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629: <%= pending.listening %><% } %> \u2014 <%= listenRemain===0?'\u062a\u0645 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0647\u062f\u0641 \u2713':`\u0628\u0627\u0642\u064a ${listenRemain} \u062f\u0642\u064a\u0642\u0629 \u0645\u0639\u062a\u0645\u062f\u0629` %></small></div>\n      <a class=\"primary full center-link\" href=\"/week\"><%= weekDone?'\u0625\u0636\u0627\u0641\u0629 \u0625\u0646\u062c\u0627\u0632 \u0622\u062e\u0631':'\u0633\u062c\u0651\u0644 \u0625\u0646\u062c\u0627\u0632\u0643' %></a>\n    <% } else { %><p class=\"muted\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0623\u0633\u0628\u0648\u0639 \u0645\u0641\u062a\u0648\u062d \u062d\u0627\u0644\u064a\u064b\u0627.</p><% } %>\n  </section>\n\n  <section class=\"card journey-card\">\n    <div class=\"section-title\"><div><span class=\"eyebrow\">\u0631\u062d\u0644\u062a\u0643</span><h2>\u062a\u0642\u062f\u0645\u0643 \u0641\u064a \u0627\u0644\u0645\u0643\u062a\u0628\u0629</h2></div><a href=\"/rank\">\u0643\u0644 \u0627\u0644\u0631\u062a\u0628</a></div>\n    <div class=\"journey-rank\"><span class=\"rank-icon small\"><%= p.rank.icon %></span><div><b><%= p.rank.name %></b><small><%= p.lifetime_minutes.toLocaleString('ar-SA') %> \u062f\u0642\u064a\u0642\u0629 \u0645\u0639\u062a\u0645\u062f\u0629</small></div></div>\n    <% if(p.nextRank){ const range=p.nextRank.min_minutes-p.rank.min_minutes; const done=p.lifetime_minutes-p.rank.min_minutes; const pct=Math.max(0,Math.min(100,Math.round(done/range*100))); %><div class=\"progress large\"><i style=\"width:<%= pct %>%\"></i></div><p class=\"rank-message\">\u0628\u0627\u0642\u064a <b><%= rankRemain %></b> \u062f\u0642\u064a\u0642\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 <%= p.nextRank.icon %> \u00ab<%= p.nextRank.name %>\u00bb</p><% } else { %><p class=\"rank-message\">\u0648\u0635\u0644\u062a \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0631\u062a\u0628\u0629 \u0641\u064a \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \ud83d\udc51</p><% } %>\n    <div class=\"wallet-box\"><span>\u0631\u0635\u064a\u062f\u0643 \u0627\u0644\u0645\u062a\u0627\u062d \u0644\u0644\u0645\u0643\u0627\u0641\u0622\u062a</span><strong><%= p.wallet_minutes.toLocaleString('ar-SA') %></strong><small>\u062f\u0642\u064a\u0642\u0629</small><a href=\"/store\">\u0634\u0627\u0647\u062f \u0645\u0627\u0630\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0633\u062a\u0628\u062f\u0627\u0644\u0647 \u2190</a></div>\n  </section>\n</div>\n\n<div class=\"grid two secondary-grid\">\n  <section class=\"card\"><div class=\"section-title\"><h2>\u0622\u062e\u0631 \u0627\u0644\u0646\u0634\u0627\u0637\u0627\u062a</h2><a href=\"/history\">\u0627\u0644\u0633\u062c\u0644 \u0643\u0627\u0645\u0644\u064b\u0627</a></div><div class=\"timeline\"><% tx.slice(0,5).forEach(t=>{ %><div><span class=\"dot\"></span><p><b><%= t.kind==='earn'?'+':t.kind==='spend'?'':'\u00b1' %><%= t.amount %> \u062f\u0642\u064a\u0642\u0629</b><small><%= t.reason %></small></p></div><% }) %></div></section>\n  <section class=\"card\"><div class=\"section-title\"><h2>\u0645\u0644\u062e\u0635 \u0631\u062d\u0644\u062a\u0643</h2></div><div class=\"mini-journey\"><div><span>\ud83d\udcd6</span><b><%= p.reading_minutes.toLocaleString('ar-SA') %></b><small>\u062f\u0642\u064a\u0642\u0629 \u0642\u0631\u0627\u0621\u0629</small></div><div><span>\ud83c\udfa7</span><b><%= p.listening_minutes.toLocaleString('ar-SA') %></b><small>\u062f\u0642\u064a\u0642\u0629 \u0627\u0633\u062a\u0645\u0627\u0639</small></div></div></section>\n</div>\n<% if(notifications.length){ %><section class=\"card notifications-card\"><div class=\"section-title\"><h2>\u0625\u0634\u0639\u0627\u0631\u0627\u062a\u0643</h2></div><div class=\"notification-list\"><% notifications.forEach(n=>{ %><div><b><%= n.title %></b><span><%= n.body %></span></div><% }) %></div></section><% } %>\n<%- include('partials/footer') %>\n",
  "admin-vouchers": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0627\u0644\u062a\u062d\u0642\u0642 \u0648\u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644</span><h1>\u0627\u0644\u0642\u0633\u0627\u0626\u0645</h1></div></div><section class=\"card\"><div class=\"table-wrap\"><table><thead><tr><th>\u0627\u0644\u0631\u0645\u0632</th><th>\u0627\u0644\u0645\u0634\u0627\u0631\u0643</th><th>\u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629</th><th>\u0627\u0644\u062d\u0627\u0644\u0629</th><th>\u0627\u0644\u0625\u062c\u0631\u0627\u0621</th></tr></thead><tbody><% vouchers.forEach(v=>{ %><tr><td><code><%= v.code %></code></td><td><b><%= v.participant_name %></b></td><td><%= v.icon %> <%= v.reward_name %></td><td><span class=\"status <%= v.status %>\"><%= v.status==='unused'?'\u063a\u064a\u0631 \u0645\u0633\u062a\u062e\u062f\u0645\u0629':v.status==='used'?'\u0645\u0633\u062a\u062e\u062f\u0645\u0629':v.status==='expired'?'\u0645\u0646\u062a\u0647\u064a\u0629':'\u0645\u0644\u063a\u0627\u0629' %></span></td><td><% if(v.status==='unused'){ %><div class=\"actions\"><form method=\"post\" action=\"/admin/vouchers/<%= v.id %>/use\"><button class=\"mini primary\" data-confirm=\"\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0642\u0633\u064a\u0645\u0629\u061f\">\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645</button></form><form method=\"post\" action=\"/admin/vouchers/<%= v.id %>/cancel\"><button class=\"mini danger\">\u0625\u0644\u063a\u0627\u0621</button></form></div><% } %></td></tr><% }) %></tbody></table></div></section><%- include('partials/footer') %>\n",
  "history": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0643\u0644 \u0634\u064a\u0621 \u0645\u0648\u062b\u0642</span><h1>\u0633\u062c\u0644 \u0645\u0643\u062a\u0628\u062a\u064a</h1></div></div><section class=\"card\"><div class=\"table-wrap\"><table><thead><tr><th>\u0627\u0644\u0639\u0645\u0644\u064a\u0629</th><th>\u0627\u0644\u062a\u063a\u064a\u064a\u0631</th><th>\u0627\u0644\u0631\u0635\u064a\u062f \u0642\u0628\u0644</th><th>\u0627\u0644\u0631\u0635\u064a\u062f \u0628\u0639\u062f</th><th>\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0631\u062d\u0644\u0629</th><th>\u0627\u0644\u062a\u0627\u0631\u064a\u062e</th></tr></thead><tbody><% tx.forEach(t=>{ %><tr><td><%= t.reason||t.kind %></td><td class=\"<%= t.amount>=0?'positive':'negative' %>\"><%= t.amount>0?'+':'' %><%= t.amount %></td><td><%= t.wallet_before %></td><td><%= t.wallet_after %></td><td><%= t.lifetime_after %></td><td><%= new Date(t.created_at).toLocaleString('ar-SA') %></td></tr><% }) %></tbody></table></div></section><%- include('partials/footer') %>\n",
  "admin-settings": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0646\u0638\u0627\u0645</span><h1>\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a</h1></div></div><section class=\"card settings-card\"><form method=\"post\" action=\"/admin/settings\"><label>\u0627\u0633\u0645 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c<input name=\"program_name\" value=\"<%= programName %>\"></label><label class=\"toggle-row\"><div><b>\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0641</b><small>\u0644\u0627 \u062a\u0636\u0627\u0641 \u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0625\u0644\u0627 \u0628\u0639\u062f \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0645\u0634\u0631\u0641.</small></div><input type=\"checkbox\" name=\"approval_required\" <%= approvalRequired==='1'?'checked':'' %>></label><label class=\"toggle-row\"><div><b>\u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u062a\u0645\u064a\u0632\u064a\u0646</b><small>\u0625\u0638\u0647\u0627\u0631 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u064a\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0648\u0642\u0639.</small></div><input type=\"checkbox\" name=\"leaderboard_enabled\" <%= leaderboardEnabled==='1'?'checked':'' %>></label><label class=\"toggle-row\"><div><b>\u0642\u0633\u0627\u0626\u0645\u064a</b><small>\u0625\u0638\u0647\u0627\u0631 \u0635\u0641\u062d\u0629 \u0627\u0644\u0642\u0633\u0627\u0626\u0645 \u0644\u0644\u0645\u0634\u0627\u0631\u0643\u064a\u0646. \u064a\u0645\u0643\u0646\u0643 \u0625\u064a\u0642\u0627\u0641\u0647\u0627 \u0645\u0624\u0642\u062a\u064b\u0627 \u0648\u062a\u0641\u0639\u064a\u0644\u0647\u0627 \u0644\u0627\u062d\u0642\u064b\u0627.</small></div><input type=\"checkbox\" name=\"vouchers_enabled\" <%= vouchersEnabled==='1'?'checked':'' %>></label><button class=\"primary\">\u062d\u0641\u0638 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a</button></form></section><%- include('partials/footer') %>\n",
  "admin-weeks": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u062e\u0637\u0629 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c</span><h1>\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0623\u0633\u0627\u0628\u064a\u0639</h1></div></div>\n<section class=\"card\"><h2>\u0625\u0636\u0627\u0641\u0629 \u0623\u0633\u0628\u0648\u0639</h2><form class=\"admin-form\" method=\"post\" action=\"/admin/weeks/add\"><div class=\"form-grid\"><label>\u0631\u0642\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639<input type=\"number\" name=\"week_number\" min=\"1\" required></label><label>\u0627\u0644\u0639\u0646\u0648\u0627\u0646<input name=\"title\" required></label><label>\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0642\u0631\u0627\u0621\u0629<input type=\"number\" name=\"reading_target\" min=\"0\" value=\"40\" required></label><label>\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639<input type=\"number\" name=\"listening_target\" min=\"0\" value=\"30\" required></label><label>\u0627\u0644\u0628\u062f\u0627\u064a\u0629<input type=\"datetime-local\" name=\"starts_at\" required></label><label>\u0627\u0644\u0646\u0647\u0627\u064a\u0629<input type=\"datetime-local\" name=\"ends_at\" required></label><label>\u0627\u0644\u062d\u0627\u0644\u0629<select name=\"status\"><option value=\"closed\">\u0645\u063a\u0644\u0642</option><option value=\"open\">\u0645\u0641\u062a\u0648\u062d</option></select></label></div><label>\u0648\u0635\u0641 \u0627\u0644\u0645\u0647\u0645\u0629<textarea name=\"description\"></textarea></label><button class=\"primary\">\u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</button></form></section>\n<div class=\"admin-cards\"><% weeks.forEach(w=>{ %><form class=\"card week-edit\" method=\"post\" action=\"/admin/weeks/<%= w.id %>/update\"><div class=\"row-between\"><span class=\"badge\">\u0627\u0644\u0623\u0633\u0628\u0648\u0639 <%= w.week_number %></span><select name=\"status\"><option value=\"closed\" <%= w.status==='closed'?'selected':'' %>>\u0645\u063a\u0644\u0642</option><option value=\"open\" <%= w.status==='open'?'selected':'' %>>\u0645\u0641\u062a\u0648\u062d</option></select></div><label>\u0627\u0644\u0639\u0646\u0648\u0627\u0646<input name=\"title\" value=\"<%= w.title %>\" required></label><div class=\"form-row\"><label>\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0642\u0631\u0627\u0621\u0629<input type=\"number\" min=\"0\" name=\"reading_target\" value=\"<%= w.reading_target %>\"></label><label>\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639<input type=\"number\" min=\"0\" name=\"listening_target\" value=\"<%= w.listening_target %>\"></label></div><label>\u0648\u0635\u0641 \u0627\u0644\u0645\u0647\u0645\u0629<textarea name=\"description\"><%= w.description %></textarea></label><div class=\"form-row\"><label>\u0627\u0644\u0628\u062f\u0627\u064a\u0629<input type=\"datetime-local\" name=\"starts_at\" value=\"<%= w.starts_at.slice(0,16) %>\"></label><label>\u0627\u0644\u0646\u0647\u0627\u064a\u0629<input type=\"datetime-local\" name=\"ends_at\" value=\"<%= w.ends_at.slice(0,16) %>\"></label></div><button class=\"primary full\">\u062d\u0641\u0638 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</button></form><% }) %></div>\n<%- include('partials/footer') %>\n",
  "week": "<%- include('partials/header') %>\n<% const approvedReading=logs.filter(l=>l.activity_type==='reading'&&l.status==='approved').reduce((s,l)=>s+l.minutes,0); const approvedListening=logs.filter(l=>l.activity_type==='listening'&&l.status==='approved').reduce((s,l)=>s+l.minutes,0); const pendingReading=logs.filter(l=>l.activity_type==='reading'&&l.status==='pending').reduce((s,l)=>s+l.minutes,0); const pendingListening=logs.filter(l=>l.activity_type==='listening'&&l.status==='pending').reduce((s,l)=>s+l.minutes,0); %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0627\u0644\u0645\u0647\u0645\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629</span><h1>\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</h1><p class=\"muted\">\u0627\u0639\u0631\u0641 \u0647\u062f\u0641\u0643\u060c \u0633\u062c\u0651\u0644 \u062f\u0642\u0627\u0626\u0642\u0643\u060c \u0648\u0627\u062a\u0631\u0643 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0644\u0644\u0645\u0634\u0631\u0641.</p></div></div>\n<% if(week){ %>\n<section class=\"card week-summary\"><div><span class=\"badge\">\u0627\u0644\u0623\u0633\u0628\u0648\u0639 <%= week.week_number %></span><h2><%= week.title %></h2><p><%= week.description %></p></div><div class=\"week-goals\"><div><span>\ud83d\udcd6</span><b><%= week.reading_target %></b><small>\u062f\u0642\u064a\u0642\u0629 \u0642\u0631\u0627\u0621\u0629</small></div><div><span>\ud83c\udfa7</span><b><%= week.listening_target %></b><small>\u062f\u0642\u064a\u0642\u0629 \u0627\u0633\u062a\u0645\u0627\u0639</small></div></div></section>\n\n<div class=\"grid two week-layout\"><section class=\"card submit-card\"><span class=\"eyebrow\">\u0623\u0636\u0641 \u062f\u0642\u0627\u0626\u0642\u0643</span><h2>\u0633\u062c\u0651\u0644 \u0625\u0646\u062c\u0627\u0632\u0643</h2><p class=\"muted\">\u0623\u062f\u062e\u0644 \u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0623\u0648 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0623\u0648 \u0643\u0644\u0627\u0647\u0645\u0627 \u0645\u0639\u064b\u0627\u060c \u062b\u0645 \u0623\u0631\u0633\u0644 \u0644\u0644\u0645\u0631\u0627\u062c\u0639\u0629.</p><form method=\"post\" action=\"/week/submit\" id=\"activity-form\"><div class=\"dual-activity\"><label class=\"activity-field\"><span>\ud83d\udcd6 \u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0642\u0631\u0627\u0621\u0629</span><input type=\"number\" name=\"reading_minutes\" min=\"0\" max=\"1440\" inputmode=\"numeric\" placeholder=\"0\"></label><label class=\"activity-field\"><span>\ud83c\udfa7 \u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639</span><input type=\"number\" name=\"listening_minutes\" min=\"0\" max=\"1440\" inputmode=\"numeric\" placeholder=\"0\"></label></div><label>\u0645\u0644\u0627\u062d\u0638\u0629 <small class=\"muted\">\u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629</small><textarea name=\"notes\" rows=\"3\" placeholder=\"\u0627\u0633\u0645 \u0627\u0644\u0643\u062a\u0627\u0628 \u0623\u0648 \u0627\u0644\u0645\u0627\u062f\u0629 \u0625\u0646 \u0623\u062d\u0628\u0628\u062a\"></textarea></label><button class=\"primary full\">\u0625\u0631\u0633\u0627\u0644 \u0644\u0644\u0645\u0631\u0627\u062c\u0639\u0629</button></form></section>\n\n<section class=\"card week-status\"><span class=\"eyebrow\">\u062d\u0627\u0644\u062a\u0643 \u0627\u0644\u0622\u0646</span><h2>\u062a\u0642\u062f\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</h2><div class=\"status-goal\"><div><span>\ud83d\udcd6 \u0627\u0644\u0642\u0631\u0627\u0621\u0629</span><b><%= approvedReading %> / <%= week.reading_target %></b></div><div class=\"progress\"><i style=\"width:<%= Math.min(100,Math.round(approvedReading/week.reading_target*100)) %>%\"></i></div><small>\u0645\u0639\u062a\u0645\u062f: <%= approvedReading %> \u062f\u0642\u064a\u0642\u0629 <% if(pendingReading){ %>\u2022 \u0642\u064a\u062f \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629: <%= pendingReading %><% } %></small></div><div class=\"status-goal\"><div><span>\ud83c\udfa7 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639</span><b><%= approvedListening %> / <%= week.listening_target %></b></div><div class=\"progress\"><i style=\"width:<%= Math.min(100,Math.round(approvedListening/week.listening_target*100)) %>%\"></i></div><small>\u0645\u0639\u062a\u0645\u062f: <%= approvedListening %> \u062f\u0642\u064a\u0642\u0629 <% if(pendingListening){ %>\u2022 \u0642\u064a\u062f \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629: <%= pendingListening %><% } %></small></div><div class=\"review-note\">\u23f3 \u0627\u0644\u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0645\u0631\u0633\u0644\u0629 \u0644\u0627 \u062a\u062f\u062e\u0644 \u0631\u0635\u064a\u062f\u0643 \u0625\u0644\u0627 \u0628\u0639\u062f \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0641.</div></section></div>\n\n<section class=\"card\"><div class=\"section-title\"><h2>\u0625\u0646\u062c\u0627\u0632\u0627\u062a\u064a \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</h2><span class=\"muted\"><%= logs.length %> \u0639\u0645\u0644\u064a\u0627\u062a</span></div><div class=\"log-cards\"><% if(!logs.length){ %><p class=\"muted\">\u0644\u0645 \u062a\u0631\u0633\u0644 \u0623\u064a \u0625\u0646\u062c\u0627\u0632 \u062d\u062a\u0649 \u0627\u0644\u0622\u0646.</p><% } %><% logs.forEach(l=>{ %><article class=\"log-card\"><div class=\"log-icon\"><%= l.activity_type==='reading'?'\ud83d\udcd6':'\ud83c\udfa7' %></div><div><b><%= l.activity_type==='reading'?'\u0642\u0631\u0627\u0621\u0629':'\u0627\u0633\u062a\u0645\u0627\u0639' %> \u2014 <%= l.minutes %> \u062f\u0642\u064a\u0642\u0629</b><small><%= new Date(l.submitted_at).toLocaleDateString('ar-SA') %></small></div><span class=\"status <%= l.status %>\"><%= l.status==='pending'?'\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f':l.status==='approved'?'\u0645\u0639\u062a\u0645\u062f':'\u0645\u0631\u0641\u0648\u0636' %></span></article><% }) %></div></section>\n<% } else { %><div class=\"empty\">\u0644\u0627 \u064a\u0648\u062c\u062f \u0623\u0633\u0628\u0648\u0639 \u0645\u0641\u062a\u0648\u062d \u062d\u0627\u0644\u064a\u064b\u0627.</div><% } %>\n<%- include('partials/footer') %>\n",
  "admin-ranks": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0633\u0644\u0645 \u0627\u0644\u062a\u0642\u062f\u0645</span><h1>\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0631\u062a\u0628</h1></div></div>\n<section class=\"card\"><h2>\u0625\u0636\u0627\u0641\u0629 \u0631\u062a\u0628\u0629</h2><form class=\"form-row\" method=\"post\" action=\"/admin/ranks/add\"><input name=\"icon\" value=\"\ud83d\udcd6\" required><input name=\"name\" placeholder=\"\u0627\u0633\u0645 \u0627\u0644\u0631\u062a\u0628\u0629\" required><input name=\"description\" placeholder=\"\u0627\u0644\u0648\u0635\u0641\"><input name=\"min_minutes\" type=\"number\" min=\"0\" placeholder=\"\u062d\u062f \u0627\u0644\u062f\u0642\u0627\u0626\u0642\" required><input name=\"sort_order\" type=\"number\" min=\"1\" placeholder=\"\u0627\u0644\u062a\u0631\u062a\u064a\u0628\" required><button class=\"primary\">\u0625\u0636\u0627\u0641\u0629</button></form></section>\n<div class=\"admin-cards\"><% ranks.forEach(r=>{ %><form class=\"card rank-edit\" method=\"post\" action=\"/admin/ranks/<%= r.id %>/update\"><div class=\"rank-icon small\"><%= r.icon %></div><label>\u0627\u0633\u0645 \u0627\u0644\u0631\u062a\u0628\u0629<input name=\"name\" value=\"<%= r.name %>\"></label><div class=\"form-row\"><label>\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0629<input name=\"icon\" value=\"<%= r.icon %>\"></label><label>\u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649<input type=\"number\" name=\"min_minutes\" min=\"0\" value=\"<%= r.min_minutes %>\"></label><label>\u0627\u0644\u062a\u0631\u062a\u064a\u0628<input type=\"number\" name=\"sort_order\" min=\"1\" value=\"<%= r.sort_order %>\"></label></div><label>\u0627\u0644\u0648\u0635\u0641<textarea name=\"description\"><%= r.description %></textarea></label><label class=\"check\"><input type=\"checkbox\" name=\"active\" <%= r.active?'checked':'' %>> \u0627\u0644\u0631\u062a\u0628\u0629 \u0645\u0641\u0639\u0644\u0629</label><button class=\"primary full\">\u062d\u0641\u0638</button></form><% }) %></div>\n<%- include('partials/footer') %>\n",
  "vouchers": "<%- include('partials/header') %><div class=\"page-head\"><div><span class=\"eyebrow\">\u0645\u0643\u0627\u0641\u0622\u062a\u0643</span><h1>\u0642\u0633\u0627\u0626\u0645\u064a</h1></div></div><div class=\"voucher-grid\"><% if(!vouchers.length){ %><div class=\"empty\">\u0644\u0645 \u062a\u0633\u062a\u0628\u062f\u0644 \u0623\u064a \u0645\u0643\u0627\u0641\u0623\u0629 \u0628\u0639\u062f.</div><% } %><% vouchers.forEach(v=>{ %><article class=\"voucher\"><div class=\"voucher-cut\"></div><div><span class=\"voucher-icon\"><%= v.icon %></span><h3><%= v.reward_name %></h3><p><%= v.description %></p><span class=\"status <%= v.status %>\"><%= v.status==='unused'?'\u063a\u064a\u0631 \u0645\u0633\u062a\u062e\u062f\u0645\u0629':v.status==='used'?'\u0645\u0633\u062a\u062e\u062f\u0645\u0629':v.status==='expired'?'\u0645\u0646\u062a\u0647\u064a\u0629':'\u0645\u0644\u063a\u0627\u0629' %></span></div><div class=\"code\"><small>\u0631\u0645\u0632 \u0627\u0644\u0642\u0633\u064a\u0645\u0629</small><strong><%= v.code %></strong><small>\u0627\u0633\u062a\u0628\u062f\u0644\u062a \u0645\u0642\u0627\u0628\u0644 <%= v.price_minutes %> \u062f\u0642\u064a\u0642\u0629</small></div></article><% }) %></div><%- include('partials/footer') %>\n",
  "admin-rewards": "<%- include('partials/header') %>\n<div class=\"page-head\"><div><span class=\"eyebrow\">\u0645\u062a\u062c\u0631 \u0627\u0644\u0645\u0643\u062a\u0628\u0629</span><h1>\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0643\u0627\u0641\u0622\u062a</h1></div></div>\n<section class=\"card\"><h2>\u0625\u0636\u0627\u0641\u0629 \u0645\u0643\u0627\u0641\u0623\u0629</h2><form method=\"post\" action=\"/admin/rewards/add\" class=\"admin-form\"><div class=\"form-grid\"><label>\u0627\u0644\u0627\u0633\u0645<input name=\"name\" required></label><label>\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0629<input name=\"icon\" value=\"\ud83c\udf81\"></label><label>\u0627\u0644\u0633\u0639\u0631 \u0628\u0627\u0644\u062f\u0642\u0627\u0626\u0642<input type=\"number\" name=\"price_minutes\" min=\"1\" required></label><label>\u0627\u0644\u0643\u0645\u064a\u0629<input type=\"number\" name=\"quantity\" min=\"0\" required></label><label>\u062a\u0628\u062f\u0623 \u0645\u0646<input type=\"datetime-local\" name=\"available_from\"></label><label>\u062a\u0646\u062a\u0647\u064a \u0641\u064a<input type=\"datetime-local\" name=\"available_until\"></label><label>\u0627\u0644\u0631\u062a\u0628\u0629 \u0627\u0644\u062f\u0646\u064a\u0627<select name=\"min_rank_id\"><option value=\"\">\u0628\u062f\u0648\u0646 \u0634\u0631\u0637</option><% ranks.forEach(r=>{ %><option value=\"<%= r.id %>\"><%= r.icon %> <%= r.name %></option><% }) %></select></label><label>\u062d\u062f \u0627\u0644\u0634\u0631\u0627\u0621<input type=\"number\" name=\"purchase_limit\" min=\"1\" placeholder=\"\u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u064b\u0627 \u0628\u0644\u0627 \u062d\u062f\"></label></div><label>\u0627\u0644\u0648\u0635\u0641<textarea name=\"description\"></textarea></label><button class=\"primary\">\u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629</button></form></section>\n<div class=\"admin-cards\"><% rewards.forEach(r=>{ %><article class=\"card\"><div class=\"row-between\"><div><h3><%= r.icon %> <%= r.name %></h3><small><%= r.active?'\u0645\u0641\u0639\u0644\u0629':'\u0645\u062a\u0648\u0642\u0641\u0629' %> \u2022 \u062a\u0645 \u0634\u0631\u0627\u0624\u0647\u0627 <%= r.buys %> \u0645\u0631\u0629 \u2022 \u0627\u0633\u062a\u062e\u062f\u0645\u062a <%= r.used %> \u0642\u0633\u064a\u0645\u0629</small></div><form method=\"post\" action=\"/admin/rewards/<%= r.id %>/toggle\"><button class=\"ghost\"><%= r.active?'\u0625\u064a\u0642\u0627\u0641':'\u062a\u0641\u0639\u064a\u0644' %></button></form></div><details><summary>\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0643\u0627\u0641\u0623\u0629</summary><form method=\"post\" action=\"/admin/rewards/<%= r.id %>/update\" class=\"admin-form\"><div class=\"form-grid\"><label>\u0627\u0644\u0627\u0633\u0645<input name=\"name\" value=\"<%= r.name %>\" required></label><label>\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0629<input name=\"icon\" value=\"<%= r.icon %>\"></label><label>\u0627\u0644\u0633\u0639\u0631<input type=\"number\" name=\"price_minutes\" min=\"1\" value=\"<%= r.price_minutes %>\" required></label><label>\u0627\u0644\u0643\u0645\u064a\u0629<input type=\"number\" name=\"quantity\" min=\"0\" value=\"<%= r.quantity %>\" required></label><label>\u062a\u0628\u062f\u0623 \u0645\u0646<input type=\"datetime-local\" name=\"available_from\" value=\"<%= r.available_from?r.available_from.slice(0,16):'' %>\"></label><label>\u062a\u0646\u062a\u0647\u064a \u0641\u064a<input type=\"datetime-local\" name=\"available_until\" value=\"<%= r.available_until?r.available_until.slice(0,16):'' %>\"></label><label>\u0627\u0644\u0631\u062a\u0628\u0629 \u0627\u0644\u062f\u0646\u064a\u0627<select name=\"min_rank_id\"><option value=\"\">\u0628\u062f\u0648\u0646 \u0634\u0631\u0637</option><% ranks.forEach(k=>{ %><option value=\"<%= k.id %>\" <%= r.min_rank_id===k.id?'selected':'' %>><%= k.icon %> <%= k.name %></option><% }) %></select></label><label>\u062d\u062f \u0627\u0644\u0634\u0631\u0627\u0621<input type=\"number\" name=\"purchase_limit\" min=\"1\" value=\"<%= r.purchase_limit||'' %>\"></label></div><label>\u0627\u0644\u0648\u0635\u0641<textarea name=\"description\"><%= r.description||'' %></textarea></label><button class=\"primary\">\u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u062f\u064a\u0644\u0627\u062a</button></form></details></article><% }) %></div>\n<%- include('partials/footer') %>\n",
  "message": "<%- include('partials/header') %><div class=\"empty\"><h2><%= title %></h2><p><%= message %></p></div><%- include('partials/footer') %>\n",
  "partials/footer": "  </main>\n</div>\n<script>\n(function(){\n  document.querySelectorAll('[data-confirm]').forEach(function(el){el.addEventListener('click',function(e){if(!confirm(el.dataset.confirm))e.preventDefault()})});\n\n  var root=document.documentElement;\n  var toggles=document.querySelectorAll('.theme-toggle');\n  function applyTheme(theme){\n    if(theme==='dark') root.dataset.theme='dark'; else delete root.dataset.theme;\n    toggles.forEach(function(btn){var dark=theme==='dark';var icon=btn.querySelector('.theme-icon');var label=btn.querySelector('.theme-label');if(icon)icon.textContent=dark?'\u2600':'\u263e';if(label)label.textContent=dark?'\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0646\u0647\u0627\u0631\u064a':'\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062f\u0627\u0643\u0646';btn.setAttribute('aria-pressed',dark?'true':'false')});\n    try{localStorage.setItem('reader-theme',theme)}catch(e){}\n  }\n  var initial=root.dataset.theme==='dark'?'dark':'light'; applyTheme(initial);\n  toggles.forEach(function(btn){btn.addEventListener('click',function(){applyTheme(root.dataset.theme==='dark'?'light':'dark')})});\n\n  var more=document.querySelector('.mobile-more');\n  var menu=document.querySelector('.mobile-more-menu');\n  if(more&&menu){more.addEventListener('click',function(){var open=!menu.hasAttribute('hidden');if(open){menu.setAttribute('hidden','');more.setAttribute('aria-expanded','false')}else{menu.removeAttribute('hidden');more.setAttribute('aria-expanded','true')}});document.addEventListener('click',function(e){if(!menu.hasAttribute('hidden')&&!menu.contains(e.target)&&!more.contains(e.target)){menu.setAttribute('hidden','');more.setAttribute('aria-expanded','false')}})}\n})();\n</script>\n</body></html>\n",
  "partials/header": "<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#17382c\"><title><%= title %> \u2014 <%= programName %></title><link rel=\"stylesheet\" href=\"/style.css\"><script>(function(){try{var s=localStorage.getItem('reader-theme');var d=s?s==='dark':window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches;if(d)document.documentElement.dataset.theme='dark'}catch(e){}})();</script></head><body>\n<div class=\"app-shell\">\n  <% if (user) { %>\n  <aside class=\"sidebar\">\n    <a class=\"brand\" href=\"/\"><span class=\"brand-mark\"><svg class=\"logo-mark\" viewBox=\"0 0 48 48\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><path d=\"M24 13c-4.2-3-9.4-4-14.4-2.8v22.4c5-1.2 10.2-.2 14.4 2.8 4.2-3 9.4-4 14.4-2.8V10.2C33.4 9 28.2 10 24 13Z\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><path d=\"M24 13v22.4\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></span><span><b><%= programName %></b><small>\u0631\u062d\u0644\u062a\u0643 \u0641\u064a \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639</small></span></a>\n    <nav>\n      <% if(user.role==='participant'){ %>\n        <a class=\"nav-home <%= path==='/dashboard'?'active':'' %>\" href=\"/dashboard\">\u2302 <span>\u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629</span></a>\n        <a class=\"nav-week <%= path==='/week'?'active':'' %>\" href=\"/week\">\ud83d\udcd6 <span>\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639</span></a>\n        <a class=\"nav-rank <%= path==='/rank'?'active':'' %>\" href=\"/rank\">\ud83c\udfdb\ufe0f <span>\u0631\u062a\u0628\u062a\u064a</span></a>\n        <a class=\"nav-store <%= path==='/store'?'active':'' %>\" href=\"/store\">\ud83d\udecd\ufe0f <span>\u0627\u0644\u0645\u062a\u062c\u0631</span></a>\n        <% if(vouchersEnabled){ %><a class=\"nav-vouchers <%= path==='/vouchers'?'active':'' %>\" href=\"/vouchers\">\ud83c\udf9f\ufe0f <span>\u0642\u0633\u0627\u0626\u0645\u064a</span></a><% } %>\n        <a class=\"nav-history <%= path==='/history'?'active':'' %>\" href=\"/history\">\ud83d\udcdc <span>\u0633\u062c\u0644 \u0645\u0643\u062a\u0628\u062a\u064a</span></a>\n        <a class=\"nav-leaderboard <%= path==='/leaderboard'?'active':'' %>\" href=\"/leaderboard\">\ud83c\udfc6 <span>\u0627\u0644\u0645\u062a\u0645\u064a\u0632\u0648\u0646</span></a>\n        <button type=\"button\" class=\"mobile-more\" aria-expanded=\"false\" aria-controls=\"mobile-more-menu\">\u2630 <span>\u0627\u0644\u0645\u0632\u064a\u062f</span></button>\n      <% } else { %>\n        <a class=\"<%= path==='/admin'?'active':'' %>\" href=\"/admin\">\ud83d\udcca <span>\u0644\u0648\u062d\u0629 \u0627\u0644\u062a\u062d\u0643\u0645</span></a>\n        <a href=\"/admin/participants\">\ud83d\udc65 <span>\u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646</span></a>\n        <a href=\"/admin/approvals\">\u23f3 <span>\u0627\u0644\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629</span></a>\n        <a href=\"/admin/weeks\">\ud83d\udcc5 <span>\u0627\u0644\u0623\u0633\u0627\u0628\u064a\u0639</span></a>\n        <a href=\"/admin/ranks\">\ud83c\udfdb\ufe0f <span>\u0627\u0644\u0631\u062a\u0628</span></a>\n        <a href=\"/admin/rewards\">\ud83d\udecd\ufe0f <span>\u0627\u0644\u0645\u062a\u062c\u0631</span></a>\n        <a href=\"/admin/vouchers\">\ud83c\udf9f\ufe0f <span>\u0627\u0644\u0642\u0633\u0627\u0626\u0645</span></a>\n        <a href=\"/admin/transactions\">\ud83d\udcdc <span>\u0633\u062c\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062a</span></a>\n        <% if(user.role==='manager'){ %><a href=\"/admin/staff\">\ud83d\udee1\ufe0f <span>\u0627\u0644\u0645\u0634\u0631\u0641\u0648\u0646</span></a><% } %>\n        <% if(user.role==='manager'){ %><a href=\"/admin/settings\">\u2699\ufe0f <span>\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a</span></a><% } %>\n      <% } %>\n    </nav>\n    <% if(user.role==='participant'){ %><div id=\"mobile-more-menu\" class=\"mobile-more-menu\" hidden><a href=\"/rank\">\ud83c\udfdb\ufe0f \u0631\u062a\u0628\u062a\u064a</a><a href=\"/history\">\ud83d\udcdc \u0633\u062c\u0644 \u0645\u0643\u062a\u0628\u062a\u064a</a><a href=\"/leaderboard\">\ud83c\udfc6 \u0627\u0644\u0645\u062a\u0645\u064a\u0632\u0648\u0646</a><a href=\"/account\">\ud83d\udd10 \u062d\u0633\u0627\u0628\u064a</a><form action=\"/logout\" method=\"post\"><button type=\"submit\">\u21aa \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c</button></form></div><% } %>\n    <form class=\"sidebar-logout\" action=\"/logout\" method=\"post\"><button class=\"ghost full\">\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062e\u0631\u0648\u062c</button></form>\n  </aside>\n  <% } %>\n  <main class=\"main <%= user?'':'auth-main' %>\">\n    <% if(user){ %><div class=\"topbar\"><div><small>\u0645\u0631\u062d\u0628\u064b\u0627\u060c</small><strong><%= user.name %></strong></div><div class=\"top-actions\"><span class=\"role\"><%= user.role==='participant'?'\u0645\u0634\u0627\u0631\u0643':user.role==='supervisor'?'\u0645\u0634\u0631\u0641':'\u0645\u062f\u064a\u0631' %></span><button type=\"button\" class=\"theme-toggle\" aria-label=\"\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0648\u0636\u0639\" title=\"\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0644\u064a\u0644\u064a \u0648\u0627\u0644\u0646\u0647\u0627\u0631\u064a\"><span class=\"theme-icon\">\u263e</span><span class=\"theme-label\">\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062f\u0627\u0643\u0646</span></button></div></div><% } else { %><button type=\"button\" class=\"theme-toggle theme-login\" aria-label=\"\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0648\u0636\u0639\"><span class=\"theme-icon\">\u263e</span><span class=\"theme-label\">\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u062f\u0627\u0643\u0646</span></button><% } %>\n    <% if(flash){ %><div class=\"flash <%= flash.type %>\"><%= flash.message %></div><% } %>\n",
};
